#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

long long modExp(long long base, int exp, int mod) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

int main() {
    int n, k, MO;
    cin >> n >> k >> MO;
    if (n % 2 != 0) {
        cout << modExp(k, n, MO) << endl;
        return 0;
    }
    vector<long long> fact(n + 1, 1), inv_fact(n + 1, 1);
    for (int i = 1; i <= n; ++i) {
        fact[i] = (fact[i - 1] * i) % MO;
    }
    inv_fact[n] = modExp(fact[n], MO - 2, MO);
    for (int i = n - 1; i >= 0; --i) {
        inv_fact[i] = (inv_fact[i + 1] * (i + 1)) % MO;
    }
    int t = n;
    vector<int> bits;
    for (int i = 0; i <= 20; ++i) {
        if (t & 1) bits.push_back(1 << i);
        t >>= 1;
    }
    int size = 1 << bits.size();
    vector<int> S(size, 0);
    for (int mask = 0; mask < size; ++mask) {
        for (int j = 0; j < (int)bits.size(); ++j) {
            if ((mask >> j) & 1) S[mask] += bits[j];
        }
    }
    vector<int> p(size, -1);
    for (int i = 0; i < size; ++i) {
        int t_idx = -1;
        for (int j = 0; j <= 20; ++j) {
            if ((i >> j) & 1) t_idx = j;
        }
        p[i] = (1 << (t_idx + 1)) + i;
    }
    vector<vector<long long>> f(k + 1, vector<long long>(size, 0));
    f[0][0] = 1;
    for (int i = 0; i < k; ++i) {
        for (int j = 0; j < size; ++j) {
            if (f[i][j] != 0) {
                for (int k_idx = p[j]; k_idx < size; k_idx = (k_idx + 1) | j) {
                    int diff = S[k_idx ^ j];
                    long long inv_val = inv_fact[diff];
                    f[i + 1][k_idx] = (f[i + 1][k_idx] + f[i][j] * inv_val) % MO;
                }
            }
        }
    }
    long long total_pow = modExp(k, n, MO);
    long long total_ans = 0;
    for (int i = 0; i <= k; ++i) {
        long long comb = (fact[k] * inv_fact[i] % MO) * inv_fact[k - i] % MO;
        total_ans = (total_ans + f[i][size - 1] * comb) % MO;
    }
    long long final_result = (total_pow - total_ans + MO) % MO;
    cout << final_result << endl;
    return 0;
}
